### Instruction:
Create a Node.js server that serves up a webpage when a GET request is received.

### Response:
const http = require('http');
const fs = require('fs');

const server = http.createServer((req, res) => {
  if (req.method === 'GET' && req.url === '/') {
    fs.readFile('index.html', (err, data) => {
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(data);
    });
  }
});

server.listen(8000);

### Instruction:
Create a Node.js web server that takes a POST request and returns a string encoded in JSON.

### Response:
const http = require('http');

const server = http.createServer((req, res) => {
  if (req.method === 'POST') {
    let body = '';
    req.on('data', function (data) {
      body += data;
    });

    req.on('end', function () {
      res.writeHead(200, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({message: body}));
    });
  }
});

server.listen(8100);

