axios.get('https://api.github.com/search/repositories?q=language:javascript&sort=stars&order=desc&per_page=100')
  .then(function (response) {
    let repos = response.data.items.filter(repo =>
      repo.language === 'JavaScript' &&
      new Date(repo.created_at).getTime() > Date.now() - 30*24*60*60*1000
    );

    repos.forEach(repo => {
      console.log(repo.name)
    });
  })
  .catch(function (error) {
    console.log(error);
  });

### Instruction:
