### Instruction:
Build a REST API with Node.js which provides the current temperature and humidity data of a given location.

### Response:
const express = require('express');
const app = express();
const http = require("http");

app.get("/api/weather/:location", (req, res, next) => {
  let location = req.params.location;
  http.get(`http://api.weatherstack.com/current?access_key=YOUR_API_KEY&query=${location}`, (response) => {
    let data = '';
    response.on('data', (chunk) => {  
      data += chunk;
    });
    response.on('end', () => {
      data = JSON.parse(data);
      let temperature = data["current"]["temperature"];
      let humidity = data["current"]["humidity"];
      let response_data = {
        temperature: temperature,
        humidity: humidity
      }
      res.json(response_data);
    });
  });
});

### Instruction:
Use Java to send an HTTP request to an API endpoint with a login form.

### Response:
import java.net.*; 
import java.io.*; 

public class HttpClient {

  public static void main(String[] args) {

    try { 
      URL url = new URL("http://example.com/api/login"); 

      HttpURLConnection con = (HttpURLConnection) url.openConnection(); 

      // Request headers
      con.setRequestMethod("POST");
      con.setRequestProperty("Content-Type", "application/json");

      // Request body
      String body = "{\"username\":\"john_doe\", \"password\":\"password123\"}";

      // Send POST request
      con.setDoOutput(true);
      DataOutputStream wr = new DataOutputStream(con.getOutputStream());
      wr.writeBytes(body);
      wr.flush();
      wr.close();

      // Output response 
      int responseCode = con.getResponseCode();
      System.out.println("Response code: " + responseCode);
      BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
      String inputLine;
      StringBuffer content = new StringBuffer();
      while ((inputLine = in.readLine()) != null) {
        content.append(inputLine);
      }
      in.close();
      System.out.println(content.toString());
    } 
    catch (Exception ex) { 
      ex.printStackTrace();
    } 
  } 
}

